# Parse the fasta file and extract all sequences
with open('sequences.fasta', 'r') as f:
    content = f.read()

# Split by header
entries = {}
current_header = None
current_seq = ""

for line in content.strip().split('\n'):
    if line.startswith('>'):
        if current_header:
            entries[current_header] = current_seq
        current_header = line[1:]
        current_seq = ""
    else:
        current_seq += line

if current_header:
    entries[current_header] = current_seq

for name, seq in entries.items():
    print(f">{name}: {len(seq)} bp")
