cd /app && perl << 'EOFPERL'
# Parse FASTA and design primers for Golden Gate assembly with BsaI-HF v2
# BsaI-HF v2 recognizes: GGTCTC(N)^(N) and cuts after 4 bases downstream
# For directional assembly, we need:
# Forward primer: 5' -> [BsaI site GGTCTC] -> [overhang] -> [15-45 bp annealing]
# Reverse primer: 5' <- [15-45 bp annealing] <- [overhang] <- [BsaI site GGTCTC]

open(my $fh, '<', 'sequences.fasta') or die "Cannot open: $!";
my %seqs;
my $current = '';
my $seq = '';

while (<$fh>) {
    chomp;
    if (/^>(\w+)/) {
        $seqs{$current} = $seq if $current;
        $current = $1;
        $seq = '';
    } else {
        $seq .= $_;
    }
}
$seqs{$current} = $seq if $current;
close($fh);

# For Golden Gate assembly with BsaI-HF v2:
# We need overhangs that match between adjacent parts
# For a one-pot assembly of input->egfp->flag->snap->output (back to input)
# Each fragment needs fwd and rev primers with BsaI sites and matching overhangs

# Strategy: Design primers with minimum annealing region (~20 bp for best results)
# that produces specific overhangs for assembly

my %templates = map { $_ => 1 } qw(input egfp flag snap);

foreach my $name (sort keys %templates) {
    my $full_seq = $seqs{$name};
    my $len = length($full_seq);

    # Take ~25 bp from start and end for primer annealing
    my $fwd_anneal = substr($full_seq, 0, 25);
    my $rev_anneal = substr($full_seq, -25);
    # Reverse complement the rev_anneal
    my $rev_anneal_rc = reverse_complement($rev_anneal);

    print "$name:\n";
    print "  Fwd anneal: $fwd_anneal (25 bp)\n";
    print "  Rev anneal: $rev_anneal_rc (25 bp)\n";
}

sub reverse_complement {
    my ($seq) = @_;
    my %comp = (A => 'T', T => 'A', G => 'C', C => 'G');
    my @chars = split //, uc($seq);
    return join '', map { $comp{$_} } reverse @chars;
}
EOFPERL

cd /app && perl << 'EOFPERL'
# Golden Gate primer design for BsaI-HF v2 assembly
# BsaI recognizes GGTCTC and cuts N bases downstream
# For Type IIS assembly, we need compatible overhangs between adjacent fragments

open(my $fh, '<', 'sequences.fasta') or die "Cannot open: $!";
my %seqs;
my $current = '';
my $seq = '';

while (<$fh>) {
    chomp;
    if (/^>(\w+)/) {
        $seqs{$current} = $seq if $current;
        $current = $1;
        $seq = '';
    } else {
        $seq .= $_;
    }
}
$seqs{$current} = $seq if $current;
close($fh);

# For one-pot golden gate assembly, we need to circularize: input -> egfp -> flag -> snap -> output -> back to input
# BsaI sites with 4bp overhangs: [GGTCTC][NNNN] cut pattern allows directional assembly
# We'll design primers with:
# Forward: 5' GGTCTC [4bp overhang 1] [15-45bp anneal] 3'
# Reverse: 5' GGTCTC [4bp overhang 2] [15-45bp anneal RC] 3'

sub reverse_complement {
    my ($seq) = @_;
    my %comp = (A => 'T', T => 'A', G => 'C', C => 'G');
    my @chars = split //, uc($seq);
    return join '', map { $comp{$_} } reverse @chars;
}

# Overhangs for directional assembly (4bp each, chosen for minimal secondary structure)
my %overhangs = (
    'input_fwd'  => 'AAAA',
    'input_rev'  => 'CCCC',
    'egfp_fwd'   => 'CCCC',
    'egfp_rev'   => 'GGGG',
    'flag_fwd'   => 'GGGG',
    'flag_rev'   => 'TTTT',
    'snap_fwd'   => 'TTTT',
    'snap_rev'   => 'AAAA',
);

# Design primers - try 20-25 bp annealing regions first
my @templates = qw(input egfp flag snap);
my @primers;

foreach my $template (@templates) {
    my $full_seq = $seqs{$template};

    # Forward primer: from start
    my $fwd_anneal = substr($full_seq, 0, 20);
    my $fwd_primer = 'GGTCTC' . $overhangs{$template.'_fwd'} . $fwd_anneal;

    # Reverse primer: from end, reverse complement
    my $rev_anneal_rc = reverse_complement(substr($full_seq, -20));
    my $rev_primer = 'GGTCTC' . $overhangs{$template.'_rev'} . $rev_anneal_rc;

    push @primers, {
        name => $template . '_fwd',
        seq => $fwd_primer,
        anneal => $fwd_anneal,
        len_anneal => 20,
    };
    push @primers, {
        name => $template . '_rev',
        seq => $rev_primer,
        anneal => $rev_anneal_rc,
        len_anneal => 20,
    };
}

# Now test Tm values - we'll iterate if needed
# First, dump primers and their annealing regions for checking
foreach my $p (@primers) {
    print "Name: $p->{name}\n";
    print "  Full primer: $p->{seq}\n";
    print "  Annealing region (20 bp): $p->{anneal}\n\n";
}
EOFPERL

