foreach my $template (@templates) {
    my $full_seq = $seqs{$template};
    my $best_pair;
    my $best_diff = 999;

    for my $fwd_len (15..45) {
        for my $rev_len (15..45) {
            my $fwd_anneal = substr($full_seq, 0, $fwd_len);
            my $rev_anneal_rc = reverse_complement(substr($full_seq, -$rev_len));

            my $fwd_tm = get_tm($fwd_anneal);
            my $rev_tm = get_tm($rev_anneal_rc);

            next if $fwd_tm < 58 || $fwd_tm > 72;
            next if $rev_tm < 58 || $rev_tm > 72;

            my $diff = abs($fwd_tm - $rev_tm);
            next if $diff > 5;

            if ($diff < $best_diff || !$best_pair) {
                $best_diff = $diff;
                $best_pair = {
                    fwd_len => $fwd_len,
                    rev_len => $rev_len,
                    fwd_anneal => $fwd_anneal,
                    rev_anneal => $rev_anneal_rc,
                    fwd_tm => $fwd_tm,
                    rev_tm => $rev_tm,
                    diff => $diff,
                };
            }
        }
    }

    if ($best_pair) {
        printf "%s: fwd_len=%d (Tm=%.1f) rev_len=%d (Tm=%.1f) diff=%.1f\n",
            $template,
            $best_pair->{fwd_len}, $best_pair->{fwd_tm},
            $best_pair->{rev_len}, $best_pair->{rev_tm},
            $best_pair->{diff};
    } else {
        print "$template: NO VALID PAIR FOUND\n";
    }
