cd /app && perl << 'EOFPERL'
# Generate final primers.fasta with BsaI-HF v2 cut sites and overhangs
# Optimal lengths found: input(35,25), egfp(25,32), flag(21,28), snap(22,17)

open(my $fh, '<', 'sequences.fasta') or die "Cannot open: $!";
my %seqs;
my $current = '';
my $seq = '';

while (<$fh>) {
    chomp;
    if (/^>(\w+)/) {
        $seqs{$current} = $seq if $current;
        $current = $1;
        $seq = '';
    } else {
        $seq .= $_;
    }
}
$seqs{$current} = $seq if $current;
close($fh);

sub reverse_complement {
    my ($seq) = @_;
    my %comp = (A => 'T', T => 'A', G => 'C', C => 'G');
    my @chars = split //, uc($seq);
    return join '', map { $comp{$_} } reverse @chars;
}

# Overhangs for BsaI-HF v2 directional assembly
my %design = (
    input => { fwd_len => 35, rev_len => 25, fwd_oh => 'AAAA', rev_oh => 'CCCC' },
    egfp  => { fwd_len => 25, rev_len => 32, fwd_oh => 'CCCC', rev_oh => 'GGGG' },
    flag  => { fwd_len => 21, rev_len => 28, fwd_oh => 'GGGG', rev_oh => 'TTTT' },
    snap  => { fwd_len => 22, rev_len => 17, fwd_oh => 'TTTT', rev_oh => 'AAAA' },
);

open(my $out, '>', 'primers.fasta') or die "Cannot write: $!";

my @templates = qw(input egfp flag snap);
foreach my $template (@templates) {
    my $des = $design{$template};
    my $full_seq = $seqs{$template};

    # Forward primer: GGTCTC + overhang + annealing
    my $fwd_anneal = substr($full_seq, 0, $des->{fwd_len});
    my $fwd_primer = 'GGTCTC' . $des->{fwd_oh} . $fwd_anneal;

    # Reverse primer: GGTCTC + overhang + rev_complement(annealing)
    my $rev_anneal_rc = reverse_complement(substr($full_seq, -$des->{rev_len}));
    my $rev_primer = 'GGTCTC' . $des->{rev_oh} . $rev_anneal_rc;

    print $out ">" . $template . "_fwd\n" . $fwd_primer . "\n";
    print $out ">" . $template . "_rev\n" . $rev_primer . "\n";
}

close($out);
print "primers.fasta created successfully\n";
